// ═════════════════════════ SHARED (the surface and the Surface Map) ═════════════════════════
// Everything both pages draw the same way: the rubber duck (below), the bow wake, the Dark Remnant's glow rings.
// The rubber duck's baked meshes and markings (DUCK_MESH, written by tools/build_duck_meshes.js — never built at run time) and its WebGL
// renderer, loaded by the surface (chromatic_nebula.html) and the Surface Map. Each page supplies, at call time: T (its tuners),
// DUCK_TYPES (the surface defines them; the map receives them from it), W / H (the scene size reflections are taken against) and invertMode.
// Two ways to draw: drawDuck3D paints a duck onto a 2D canvas (an offscreen GL renderer, copied over); drawDuckScene draws one straight
// into a page's own WebGL scene with its camera (the Surface Map), so it is lit, sized and placed in true 3D there.
// ── Storage (shared): one IndexedDB key-value store for both pages — the surface's saved session, a backup of the save, and the Surface
// Map's cached hex pictures. (localStorage is small and silently refuses writes when full; this has room.)
const IDB={db:null,
  open(){return this.db||(this.db=new Promise((ok,no)=>{const r=indexedDB.open('infiniteLight',1);r.onupgradeneeded=()=>r.result.createObjectStore('kv');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);}));},
  async run(mode,fn){const db=await this.open();return new Promise((ok,no)=>{const tx=db.transaction('kv',mode),st=tx.objectStore('kv'),q=fn(st);tx.oncomplete=()=>ok(q&&q.result);tx.onerror=()=>no(tx.error);});},
  get(k){return this.run('readonly',st=>st.get(k));},put(k,v){return this.run('readwrite',st=>st.put(v,k));},del(k){return this.run('readwrite',st=>st.delete(k));},keys(){return this.run('readonly',st=>st.getAllKeys());}};
